using System;
using Microsoft.Extensions.DependencyInjection;

namespace DiLifecycleDemo
{
    // 带 ID 的接口，用于追踪实例是否被复用
    public interface ITracker { Guid Id { get; } }

    public class Tracker : ITracker, IDisposable
    {
        public Guid Id { get; } = Guid.NewGuid();
        public void Dispose() => Console.WriteLine($"  Dispose Tracker {Id:N8}");
    }

    // 一个 Scoped 服务（模拟 DbContext）
    public interface IDbContext { Guid Id { get; } }
    public class AppDbContext : IDbContext, IDisposable
    {
        public Guid Id { get; } = Guid.NewGuid();
        public void Dispose() => Console.WriteLine($"  Dispose AppDbContext {Id:N8}");
    }

    // 正确做法：Scoped 服务依赖 Scoped DbContext
    public class OrderService
    {
        public IDbContext DbContext { get; }
        public OrderService(IDbContext dbContext) => DbContext = dbContext;
    }

    // 错误做法：Singleton 服务注入 Scoped DbContext（captive dependency）
    // 取消注释可看到 ValidateScopes 报错
    // public class BadSingletonCache
    // {
    //     public IDbContext DbContext { get; }
    //     public BadSingletonCache(IDbContext dbContext) => DbContext = dbContext;
    // }

    // 修复做法：Singleton 通过 IServiceScopeFactory 按需创建 scope
    public class GoodSingletonCache
    {
        private readonly IServiceScopeFactory _scopeFactory;
        public GoodSingletonCache(IServiceScopeFactory scopeFactory) => _scopeFactory = scopeFactory;

        public Guid GetDbContextId()
        {
            using var scope = _scopeFactory.CreateScope();
            var ctx = scope.ServiceProvider.GetRequiredService<IDbContext>();
            return ctx.Id;
        }
    }

    class Program
    {
        static void Main()
        {
            var services = new ServiceCollection();
            services.AddTransient<ITracker, Tracker>();
            services.AddScoped<IDbContext, AppDbContext>();
            services.AddScoped<OrderService>();
            services.AddSingleton<GoodSingletonCache>();

            // 开发环境默认 ValidateScopes=true，可捕获 captive dependency
            var provider = services.BuildServiceProvider(
                new ServiceProviderOptions { ValidateScopes = true });

            // 1. Transient 每次新建
            Console.WriteLine("=== Transient ===");
            var t1 = provider.GetRequiredService<ITracker>();
            var t2 = provider.GetRequiredService<ITracker>();
            Console.WriteLine($"t1={t1.Id:N8}, t2={t2.Id:N8}, same={t1.Id == t2.Id}");

            // 2. Scoped 同 scope 复用，跨 scope 独立
            Console.WriteLine("\n=== Scoped ===");
            using (var s1 = provider.CreateScope())
            {
                var ctx1 = s1.ServiceProvider.GetRequiredService<IDbContext>();
                var ctx2 = s1.ServiceProvider.GetRequiredService<IDbContext>();
                Console.WriteLine($"scope1: ctx1={ctx1.Id:N8}, ctx2={ctx2.Id:N8}, same={ctx1.Id == ctx2.Id}");
            }
            using (var s2 = provider.CreateScope())
            {
                var ctx3 = s2.ServiceProvider.GetRequiredService<IDbContext>();
                Console.WriteLine($"scope2: ctx3={ctx3.Id:N8}");
            }

            // 3. Singleton 通过 scope factory 按需使用 Scoped 服务
            Console.WriteLine("\n=== Singleton + ScopeFactory ===");
            var cache = provider.GetRequiredService<GoodSingletonCache>();
            Console.WriteLine($"cache gets ctx id={cache.GetDbContextId():N8}");
            Console.WriteLine($"cache gets ctx id={cache.GetDbContextId():N8} (new each time)");

            provider.Dispose();
        }
    }
}
